export function getKioskLanguage(code) {
  const language = kioskLanguages.find((item) => item.code === code) || kioskLanguages[0];
  return {
    ...language,
    messages: {
      ...language.messages,
      ...kioskMenuCopy[language.code],
      ...kioskExperienceCopy[language.code],
      ...kioskNextCopy[language.code],
      officialSlogan: officialSlogans[language.code],
      welcomeReassurance: hospitalityMessages[language.code].headline,
      welcomeHospitality: hospitalityMessages[language.code].supporting,
      ...reportPresentationCopy[language.code],
      otherLanguages: otherLanguageLabels[language.code],
      ...manualProgressCopy[language.code],
      manualCampaignName: manualCampaignLabels[language.code],
      ...manualPilgrimFieldLabels[language.code],
      manualReject: manualRejectLabels[language.code],
      ...reportUiCopy[language.code],
      ...reportRelationCopy[language.code],
      ...reportTrackingCopy[language.code],
    },
  };
}
